svg.script:
//
const irisL = document.getElementById('iris-l');
const irisR = document.getElementById('iris-r');
const face = document.getElementById('face-assembly');
const browL = document.getElementById('eyebrow-l');
const browR = document.getElementById('eyebrow-r');
const wrinkles = document.getElementById('forehead-wrinkles');
const statusText = document.getElementById('status-badge-text');
const statusBg = document.getElementById('badge-bg');

const detailsTitle = document.getElementById('details-title');
const detailsBody1 = document.getElementById('details-body-1');
const detailsBody2 = document.getElementById('details-body-2');
const detailsBody3 = document.getElementById('details-body-3');
const detailsBody4 = document.getElementById('details-body-4');
const detailsBody5 = document.getElementById('details-body-5');
const detailsBody6 = document.getElementById('details-body-6');
const detailsBody7 = document.getElementById('details-body-7');

let vibrationInterval = null;

function setEyes(x, y) {
  irisL.setAttribute('transform', `translate(${x}, ${y})`);
  irisR.setAttribute('transform', `translate(${x}, ${y})`);
}

function clearEffects() {
  clearInterval(vibrationInterval);
  face.setAttribute('transform', 'translate(0, 0)');

  // Resetar rugas e sobrancelhas para o estado padrão
  const wrinkleChildren = wrinkles.getElementsByClassName('wrinkle');
  for (let i = 0; i < wrinkleChildren.length; i++) {
    wrinkleChildren[i].style.opacity = '0';
  }
  browL.setAttribute('d', 'M 170 170 Q 215 160 260 178');
  browR.setAttribute('d', 'M 320 178 Q 365 160 410 170');
}

function selectBtn(activeId) {
  ['btn-up', 'btn-down', 'btn-rvo'].forEach(id => {
    const btn = document.getElementById(id);
    if (btn) btn.classList.remove('active');
  });
  const activeBtn = document.getElementById(activeId);
  if (activeBtn) activeBtn.classList.add('active');
}

function setClinicalState(state) {
  clearEffects();

  if (state === 'up') {
    selectBtn('btn-up');
    setEyes(0, -22);

    statusText.textContent = "CONJUGADO ACIMA";
    statusText.className.baseVal = "status-badge badge-amber";
    statusBg.className.baseVal = "badge-bg badge-bg-amber";

    detailsTitle.textContent = "OLHAR VERTICAL SUPERIOR";
    detailsTitle.style.fill = "var(--amber)";

    detailsBody1.textContent = "O paciente consegue elevar o olhar voluntariamente.";
    detailsBody2.textContent = "Esse movimento é geralmente mantido no início";
    detailsBody3.textContent = "e fases intermediárias da doença (PSP).";
    detailsBody4.textContent = "O tônus extensor cervical (retrocolo) acompanha";
    detailsBody5.textContent = "este achado. O paciente tende a tombar a";
    detailsBody6.textContent = "cabeça para trás para tentar compensar o olhar.";
    detailsBody7.textContent = "Clique nos botões de testes ou nós da via abaixo.";

    showPathwayDetail('cortex', true);
  } else if (state === 'down') {
    selectBtn('btn-down');

    // Posição das sobrancelhas mostrando esforço
    browL.setAttribute('d', 'M 170 160 Q 215 178 260 172');
    browR.setAttribute('d', 'M 320 172 Q 365 178 410 160');

    const wrinkleChildren = wrinkles.getElementsByClassName('wrinkle');
    for (let i = 0; i < wrinkleChildren.length; i++) {
      wrinkleChildren[i].style.opacity = '0.95';
    }

    // Simulação da tentativa voluntária bloqueada com tremor (nistagmo de esforço)
    let count = 0;
    vibrationInterval = setInterval(() => {
      count++;
      const dx = (Math.random() - 0.5) * 3;
      const dy = 2 + (Math.random() - 0.5) * 2; // tenta descer mas vibra
      setEyes(dx, dy);

      if (count > 16) {
        clearInterval(vibrationInterval);
        // Trava totalmente no desvio superior
        setEyes(0, -18);

        statusText.textContent = "PARALISIA VERTICAL";
        statusText.className.baseVal = "status-badge badge-red";
        statusBg.className.baseVal = "badge-bg badge-bg-red";

        detailsTitle.textContent = "FALHA VOLUNTÁRIA PARA BAIXO";
        detailsTitle.style.fill = "var(--red)";

        detailsBody1.textContent = "O comando voluntário de descida falha completamente.";
        detailsBody2.textContent = "Os olhos esboçam leve descida, sofrem tremor";
        detailsBody3.textContent = "vertical espasmódico e são puxados para cima.";
        detailsBody4.textContent = "MECANISMO DA PSP:";
        detailsBody5.textContent = "A degeneração atinge vias supranucleares rostral do";
        detailsBody6.textContent = "FLM. O estímulo voluntário de descida não alcança";
        detailsBody7.textContent = "os núcleos do tronco cerebral.";

        showPathwayDetail('lesion', true);
      }
    }, 45);
  } else if (state === 'rvo') {
    selectBtn('btn-rvo');

    // Simula inclinação passiva da cabeça para trás (movimento para cima)
    face.setAttribute('transform', 'translate(0, -22) scale(0.96) translate(12, 10)');

    // O Reflexo Vestíbulo-Ocular (RVO) faz os olhos descerem perfeitamente
    setEyes(0, 22);

    statusText.textContent = "RVO PRESERVADO";
    statusText.className.baseVal = "status-badge badge-green";
    statusBg.className.baseVal = "badge-bg badge-bg-green";

    detailsTitle.textContent = "REFLEXO VESTÍBULO-OCULAR (RVO)";
    detailsTitle.style.fill = "var(--green)";

    detailsBody1.textContent = "Ao estender a cabeça passivamente (olhos de boneca),";
    detailsBody2.textContent = "o paciente realiza a descida coordenada dos olhos.";
    detailsBody3.textContent = "Isso comprova a integridade da via de tronco.";
    detailsBody4.textContent = "VALOR DIAGNÓSTICO:";
    detailsBody5.textContent = "Os núcleos do III e IV pares e os músculos extraoculares";
    detailsBody6.textContent = "funcionam perfeitamente. A lesão reside unicamente";
    detailsBody7.textContent = "acima dos núcleos (paralisia supranuclear).";

    showPathwayDetail('tronco', true);
  }
}

function showPathwayDetail(node, fromStateSync = false) {
  if (!fromStateSync) {
    clearEffects();
  }

  // Remove classe ativa de todos os nós do diagrama
  ['node-cortex', 'node-lesion', 'node-tronco', 'node-musculo'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove('active-node');
  });

  const activeEl = document.getElementById('node-' + node);
  if (activeEl) activeEl.classList.add('active-node');

  if (fromStateSync) return; // Se a chamada veio da sincronização de estado principal, não reescreve

  if (node === 'cortex') {
    detailsTitle.textContent = "CÓRTEX MOTOR VERTICAL";
    detailsTitle.style.fill = "var(--cyan)";
    detailsBody1.textContent = "Área cortical responsável pela coordenação voluntária";
    detailsBody2.textContent = "do olhar vertical e conjugado. Envia vias do";
    detailsBody3.textContent = "trato corticobulbar em direção ao tronco.";
    detailsBody4.textContent = "ESTRUTURA ACOMETIDA:";
    detailsBody5.textContent = "Os neurônios corticais de comando estão preservados,";
    detailsBody6.textContent = "mas a projeção axonal descendente está isolada";
    detailsBody7.textContent = "pela lesão localizada logo abaixo.";
  } else if (node === 'lesion') {
    detailsTitle.textContent = "LESÃO SUPRANUCLEAR";
    detailsTitle.style.fill = "var(--red)";
    detailsBody1.textContent = "Lesão característica da Paralisia Supranuclear";
    detailsBody2.textContent = "Progressiva (PSP) que impede o sinal voluntário";
    detailsBody3.textContent = "de alcançar os núcleos motores inferiores.";
    detailsBody4.textContent = "MARCADOR DE PSP:";
    detailsBody5.textContent = "Indica que o bloqueio motor está 'acima dos núcleos'.";
    detailsBody6.textContent = "Clinicamente demonstrado pela preservação do reflexo";
    detailsBody7.textContent = "vestíbulo-ocular passivo (RVO).";
  } else if (node === 'tronco') {
    detailsTitle.textContent = "NÚCLEOS DO TRONCO CEREBRAL";
    detailsTitle.style.fill = "var(--cyan)";
    detailsBody1.textContent = "O tronco (mesencéfalo) abriga o núcleo do nervo";
    detailsBody2.textContent = "oculomotor (III par) e o centro gerador vertical";
    detailsBody3.textContent = "do olhar conjugado (complexo rostral do FLM).";
    detailsBody4.textContent = "INOCUIDADE DO TRONCO:";
    detailsBody5.textContent = "Na PSP clássica, estes núcleos e suas vias reflexas";
    detailsBody6.textContent = "estão preservados, permitindo o movimento reflexo";
    detailsBody7.textContent = "quando ativados pela via vestibular (RVO).";
  } else if (node === 'musculo') {
    detailsTitle.textContent = "EFETOR EXTRAOCULAR";
    detailsTitle.style.fill = "var(--cyan)";
    detailsBody1.textContent = "Os músculos extraoculares (reto inferior e oblíquo";
    detailsBody2.textContent = "superior) realizam a tração mecânica do globo";
    detailsBody3.textContent = "ocular para permitir o olhar inferior.";
    detailsBody4.textContent = "AUSÊNCIA DE PARALISIA PERIFÉRICA:";
    detailsBody5.textContent = "Não há fraqueza muscular ou neuropatia periférica.";
    detailsBody6.textContent = "A musculatura está totalmente apta para agir,";
    detailsBody7.textContent = "apenas aguarda um estímulo que chega pelo RVO.";
  }
}

// Inicialização default
setClinicalState('up');
//
